import{_ as o,c as t,o as a,ae as l}from"./chunks/framework.Bi6zybwU.js";const g=JSON.parse('{"title":"Table Color Settings","description":"Table Color Settings","frontmatter":{"title":"Table Color Settings","description":"Table Color Settings"},"headers":[],"relativePath":"guide/styling-design/table-color-settings.md","filePath":"guide/styling-design/table-color-settings.md"}'),s={name:"guide/styling-design/table-color-settings.md"};function r(n,e,i,c,h,d){return a(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="table-color-settings" tabindex="-1">Table Color Settings <a class="header-anchor" href="#table-color-settings" aria-label="Permalink to &quot;Table Color Settings&quot;">​</a></h1><p>Customize table colors with Ninja Tables efficiently with the Table Color Settings. Color customization is an awesome feature that lets you control the table designs and appearance. You can make your data tables more engaging and captivating using colors.</p><h2 id="how-to-customize-table-color" tabindex="-1">How to Customize Table Color <a class="header-anchor" href="#how-to-customize-table-color" aria-label="Permalink to &quot;How to Customize Table Color&quot;">​</a></h2><ul><li>First, you must set up a Table using the Ninja Tables plugin.</li><li>Select a table to customize its colors and click on the** **&quot;<strong>Table Design</strong>&quot; tab.</li><li>On the right side, a sidebar appears with 3 separate segments. Select <strong>Table Colors</strong> from the second segment.</li><li>The** Table Color** tab appears with its functions. You will notice a dropdown list of various preset colors in the <strong>Pre-Defined Scheme</strong> option. And a <strong>Custom Scheme</strong> option. <img src="https://ninjatables.com/wp-content/uploads/2025/05/New-Ui-table-color-options-1024x536.webp" alt="New Ui table color options"> We&#39;ll explain each option one by one.</li></ul><h3 id="pre-defined-color-scheme" tabindex="-1">Pre-defined Color Scheme <a class="header-anchor" href="#pre-defined-color-scheme" aria-label="Permalink to &quot;Pre-defined Color Scheme&quot;">​</a></h3><p>The color of the tables changes according to the pre-set color combination you choose. Ninja Tables offers 13 predefined color combinations. Here&#39;s an example of a table with a pre-defined color scheme of &quot;White.&quot; Once you select this color, the table will change its color combination to white and teal. <img src="https://ninjatables.com/wp-content/uploads/2025/05/New-Ui-predefined-color-scheme-1024x437.webp" alt="New Ui predefined color scheme"></p><h3 id="custom-color-scheme" tabindex="-1">Custom Color Scheme <a class="header-anchor" href="#custom-color-scheme" aria-label="Permalink to &quot;Custom Color Scheme&quot;">​</a></h3><p>Pre-defined color combinations can&#39;t always look good for your tables. Color the table with any combination you want using the Custom Color Scheme.</p><ul><li>To do so, click the <strong>Custom Scheme</strong> option in the <strong>Select Color Scheme</strong> section. Then select the color of your choice. <img src="https://ninjatables.com/wp-content/uploads/2025/05/New-ui-custom-color-settings-1024x643.webp" alt="New ui custom color settings"></li><li>Under the **Table Body Colors **part, you will find the <strong>Hover</strong> tab on the right side. Customize the hover color according to your needs. Hover over the table and see the row/text colors change. This will make the table more interactive.</li><li>You can also toggle &quot;<strong>Alternate Color Schema for Table Rows</strong>&quot; on to make the table color have alternate colors for rows. Choose your preferred custom colors to display them on odd rows and even rows. You can also change the color of your table with CSS. Check out this <strong><a href="https://ninjatables.com/docs/table-styling-css-selector/" target="_blank" rel="noreferrer">documentation</a></strong>. Also, check out - <strong><a href="https://ninjatables.com/docs/table-font-setting/" target="_blank" rel="noreferrer"> Table Font Setting</a></strong>.</li></ul>',9)])])}const m=o(s,[["render",r]]);export{g as __pageData,m as default};
